                return 0
            visited[node] = True
            depth[node] = d
            max_child_depth = 0
            for neighbor in graph[node]:
                if neighbor != parent:
                    child_depth = dfs(neighbor, node, d + 1)
                    if child_depth > max_child_depth:
                        max_child_depth = child_depth
            return max_child_depth

